import {sum,stats} from './model.js';
import {executeSell,executeBuy,marketDepth,depthLadder} from './market.js';
/** External order-book evidence is not protocol-owned liquidity. No live data is fetched. */
export function parseOrderBookCSV(text){const lines=text.replace(/^\uFEFF/,'').trim().split(/\r?\n/).filter(Boolean);if(lines.length<2)throw Error('CSV must contain a header and at least one order.');const header=lines.shift().split(',').map(x=>x.trim().toLowerCase());const index=k=>header.indexOf(k);for(const k of ['side','price','quantity'])if(index(k)<0)throw Error('Missing CSV column: '+k);const rows=lines.map((line,i)=>{const cols=line.split(',').map(x=>x.trim());const side=cols[index('side')].toLowerCase(),price=Number(cols[index('price')]),quantity=Number(cols[index('quantity')]);if(!['bid','ask','buy','sell'].includes(side)||!Number.isFinite(price)||price<=0||!Number.isFinite(quantity)||quantity<=0)throw Error('Invalid order on line '+(i+2));return {side:side==='buy'?'bid':side==='sell'?'ask':side,price,quantity,venue:index('venue')>=0?cols[index('venue')]:'Imported'};});return rows;}
export function analyzeSnapshot(rows,c,mid=null){if(!rows.length)throw Error('Empty order book.');const bids=rows.filter(r=>r.side==='bid').sort((a,b)=>b.price-a.price),asks=rows.filter(r=>r.side==='ask').sort((a,b)=>a.price-b.price);const reference=mid||((bids[0]?.price||c.launchPrice)+(asks[0]?.price||c.launchPrice))/2;if(!Number.isFinite(reference)||reference<=0)throw Error('Invalid reference price.');const m={mid:reference,bids:bids.map(r=>({bps:Math.max(0,(1-r.price/reference)*1e4),cash:r.price*r.quantity})),asks:asks.map(r=>({bps:Math.max(0,(r.price/reference-1)*1e4),tokens:r.quantity})),x:0,y:0,cexFee:c.liquidity.cexFee,dexFee:c.liquidity.dexFee,externalArbCash:0,externalArbTokens:0};const depths=depthLadder(m),trade=executeSell(m,c.liquidity.tradeTarget),buy=executeBuy(m,c.liquidity.tradeTarget*reference);return {mid:reference,levels:rows.length,venues:[...new Set(rows.map(r=>r.venue))],bidQuote:sum(bids.map(r=>r.price*r.quantity)),askTokens:sum(asks.map(r=>r.quantity)),spread:bids.length&&asks.length?(asks[0].price-bids[0].price)/reference:0,depths,trade,buy,bids,asks,warning:'User-supplied snapshot only. No freshness, ownership, spoofing, latency or venue connectivity verification. Identical cross-venue quotes may not be independently executable. No DEX liquidity is assumed.'};}
